item.query:
ВЫБРАТЬ ИС_Ozon_Заказproducts.НоменклатураOzon КАК НоменклатураOzon, ИС_Ozon_Заказproducts.Ссылка.Номер КАК НомерОтправления, ИС_Ozon_ДанныеУслуг.operation_type КАК ТипОперации, ИС_Ozon_ДанныеУслуг.type КАК ТипНачислений, ИС_Ozon_ДанныеУслуг.sale_commission КАК Комиссия, ИС_Ozon_СоответствиеХарактеристик.Номенклатура КАК Номенклатура, ИС_Ozon_СоответствиеХарактеристик.Характеристика КАК Характеристика, ВЫБОР КОГДА ИС_Ozon_ДанныеУслуг.type = ЗНАЧЕНИЕ(Перечисление.ИС_Ozon_ТипыОперацийВТранзакциях.orders) И ИС_Ozon_ДанныеУслуг.sale_commission = 0 ТОГДА ИС_Ozon_ДанныеУслуг.amount ИНАЧЕ ВЫБОР КОГДА ИС_Ozon_ДанныеУслуг.type = ЗНАЧЕНИЕ(Перечисление.ИС_Ozon_ТипыОперацийВТранзакциях.orders) И НЕ ИС_Ozon_ДанныеУслуг.sale_commission = 0 ТОГДА (ИС_Ozon_ДанныеУслуг.accruals_for_sale + ИС_Ozon_ДанныеУслуг.sale_commission - ИС_Ozon_ДанныеУслуг.amount) * -1 ИНАЧЕ 0 КОНЕЦ КОНЕЦ КАК УслугиПоПродажам, ВЫБОР КОГДА ИС_Ozon_ДанныеУслуг.type = ЗНАЧЕНИЕ(Перечисление.ИС_Ozon_ТипыОперацийВТранзакциях.returns) И ЕСТЬNULL(ИС_Ozon_ДанныеУслуг.sale_commission, 0) = 0 ТОГДА (ИС_Ozon_ДанныеУслуг.accruals_for_sale + ИС_Ozon_ДанныеУслуг.sale_commission - ИС_Ozon_ДанныеУслуг.amount) * -1 ИНАЧЕ 0 КОНЕЦ КАК УслугиПоВозвратамИОтменам, ВЫБОР КОГДА ИС_Ozon_ДанныеУслуг.type = ЗНАЧЕНИЕ(Перечисление.ИС_Ozon_ТипыОперацийВТранзакциях.services) ТОГДА ИС_Ozon_ДанныеУслуг.amount ИНАЧЕ 0 КОНЕЦ КАК СервисныеСборы, ВЫБОР КОГДА ИС_Ozon_ДанныеУслуг.type = ЗНАЧЕНИЕ(Перечисление.ИС_Ozon_ТипыОперацийВТранзакциях.compensation) ТОГДА ИС_Ozon_ДанныеУслуг.amount ИНАЧЕ 0 КОНЕЦ КАК Компенсации, ВЫБОР КОГДА ИС_Ozon_ДанныеУслуг.type = ЗНАЧЕНИЕ(Перечисление.ИС_Ozon_ТипыОперацийВТранзакциях.transfer_delivery) ТОГДА ИС_Ozon_ДанныеУслуг.amount ИНАЧЕ 0 КОНЕЦ КАК СтоимостьДоставки, ВЫБОР КОГДА ИС_Ozon_ДанныеУслуг.type = ЗНАЧЕНИЕ(Перечисление.ИС_Ozon_ТипыОперацийВТранзакциях.other) ТОГДА ИС_Ozon_ДанныеУслуг.amount ИНАЧЕ 0 КОНЕЦ КАК Прочее, ИС_Ozon_ДанныеУслуг.operation_type_name КАК operation_type_name, ИС_Ozon_Заказproducts.Ссылка КАК Ссылка ПОМЕСТИТЬ ВТ_Услуги ИЗ Документ.ИС_Ozon_Заказ.products КАК ИС_Ozon_Заказproducts ПОЛНОЕ СОЕДИНЕНИЕ РегистрСведений.ИС_Ozon_ДанныеУслуг КАК ИС_Ozon_ДанныеУслуг ПО ИС_Ozon_Заказproducts.Ссылка.Номер = ИС_Ozon_ДанныеУслуг.posting_number ПОЛНОЕ СОЕДИНЕНИЕ РегистрСведений.ИС_Ozon_СоответствиеХарактеристик КАК ИС_Ozon_СоответствиеХарактеристик ПО ИС_Ozon_Заказproducts.НоменклатураOzon = ИС_Ozon_СоответствиеХарактеристик.НоменклатураOzon ГДЕ ИС_Ozon_Заказproducts.Ссылка.Профиль = &Профиль И ИС_Ozon_СоответствиеХарактеристик.НоменклатураOzon.Профиль = &Профиль И (ИС_Ozon_Заказproducts.Ссылка.Склад В (&Склад) ИЛИ &ВсеСклады) И ИС_Ozon_Заказproducts.Ссылка.Дата МЕЖДУ &НачалоПериода И &КонецПериода И НЕ ИС_Ozon_ДанныеУслуг.type ЕСТЬ NULL И (ИС_Ozon_СоответствиеХарактеристик.Номенклатура В (&Номенклатура) ИЛИ &ВсяНоменклатура) И НЕ ИС_Ozon_СоответствиеХарактеристик.Номенклатура ЕСТЬ NULL ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ ВТ_Услуги.НоменклатураOzon КАК НоменклатураOzon, ВТ_Услуги.НомерОтправления КАК НомерОтправления, ВТ_Услуги.ТипОперации КАК ТипОперации, ВТ_Услуги.ТипНачислений КАК ТипНачислений, СУММА(ВТ_Услуги.Комиссия) КАК Комиссия, ВТ_Услуги.Номенклатура КАК Номенклатура, ВТ_Услуги.Характеристика КАК Характеристика, СУММА(ВТ_Услуги.УслугиПоПродажам) КАК УслугиПоПродажам, СУММА(ВТ_Услуги.УслугиПоВозвратамИОтменам) КАК УслугиПоВозвратамИОтменам, СУММА(ВТ_Услуги.СервисныеСборы) КАК СервисныеСборы, СУММА(ВТ_Услуги.Компенсации) КАК Компенсации, СУММА(ВТ_Услуги.СтоимостьДоставки) КАК СтоимостьДоставки, СУММА(ВТ_Услуги.Прочее) КАК Прочее, ВТ_Услуги.operation_type_name КАК НазваниеТипаОперации, ВТ_Услуги.Ссылка КАК Заказ, ВТ_Услуги.Ссылка.Склад КАК Склад ИЗ ВТ_Услуги КАК ВТ_Услуги
СГРУППИРОВАТЬ ПО ВТ_Услуги.НоменклатураOzon, ВТ_Услуги.НомерОтправления, ВТ_Услуги.ТипОперации, ВТ_Услуги.ТипНачислений, ВТ_Услуги.Номенклатура, ВТ_Услуги.Характеристика, ВТ_Услуги.operation_type_name, ВТ_Услуги.Ссылка

dataSet.query:
ВЫБРАТЬ ИС_Ozon_СоответствиеХарактеристик.НоменклатураOzon КАК НоменклатураOzon, ИС_Ozon_СоответствиеХарактеристик.Номенклатура КАК Номенклатура, ИС_Ozon_СоответствиеХарактеристик.Характеристика КАК Характеристика, ЕСТЬNULL(ИС_Ozon_СоответствиеХарактеристик.Характеристика.ХарактеристикаНоменклатурыДляЦенообразования, ЗНАЧЕНИЕ(Справочник.ХарактеристикиНоменклатурыДляЦенообразования.ПустаяСсылка)) КАК ХарактеристикаЦО, ИС_Ozon_СоответствиеХарактеристик.Упаковка КАК Упаковка, ЕСТЬNULL(ИС_Ozon_СоответствиеХарактеристик.Номенклатура.ТипНоменклатуры, ЗНАЧЕНИЕ(Перечисление.ТипыНоменклатуры.ПустаяСсылка)) = ЗНАЧЕНИЕ(Перечисление.ТипыНоменклатуры.Набор) КАК ЭтоНабор, ВЫБОР КОГДА ИС_Ozon_СоответствиеХарактеристик.Упаковка.Числитель = 0 ТОГДА 1 ИНАЧЕ ЕСТЬNULL(ИС_Ozon_СоответствиеХарактеристик.Упаковка.Числитель, 1) КОНЕЦ / ВЫБОР КОГДА ИС_Ozon_СоответствиеХарактеристик.Упаковка.Знаменатель = 0 ТОГДА 1 ИНАЧЕ ЕСТЬNULL(ИС_Ozon_СоответствиеХарактеристик.Упаковка.Знаменатель, 1) КОНЕЦ КАК КоэффициентУпаковки ПОМЕСТИТЬ ВТ_Сопоставление ИЗ РегистрСведений.ИС_Ozon_СоответствиеХарактеристик КАК ИС_Ozon_СоответствиеХарактеристик ГДЕ ИС_Ozon_СоответствиеХарактеристик.НоменклатураOzon.Профиль = &Профиль И (ИС_Ozon_СоответствиеХарактеристик.Номенклатура В (&Номенклатура) ИЛИ &ВсяНоменклатура) ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ ИСТИНА КАК РассчитываетсяИзЦенКомплектующих, ВариантыКомплектацииНоменклатуры.Владелец КАК Номенклатура, ВариантыКомплектацииНоменклатуры.Характеристика КАК Характеристика, ВариантыКомплектацииНоменклатурыТовары.Номенклатура КАК НоменклатураНабора, ВариантыКомплектацииНоменклатурыТовары.Характеристика КАК ХарактеристикаНабора, ВЫБОР КОГДА ВариантыКомплектацииНоменклатурыТовары.Упаковка.Числитель = 0 ТОГДА 1 ИНАЧЕ ЕСТЬNULL(ВариантыКомплектацииНоменклатурыТовары.Упаковка.Числитель, 1) КОНЕЦ / ВЫБОР КОГДА ВариантыКомплектацииНоменклатурыТовары.Упаковка.Знаменатель = 0 ТОГДА 1 ИНАЧЕ ЕСТЬNULL(ВариантыКомплектацииНоменклатурыТовары.Упаковка.Знаменатель, 1) КОНЕЦ КАК КоэффициентУпаковки, ВариантыКомплектацииНоменклатурыТовары.КоличествоУпаковок КАК КоличествоНабора ПОМЕСТИТЬ ВТ_СоставНаборов ИЗ Справочник.ВариантыКомплектацииНоменклатуры.Товары КАК ВариантыКомплектацииНоменклатурыТовары ЛЕВОЕ СОЕДИНЕНИЕ Справочник.ВариантыКомплектацииНоменклатуры КАК ВариантыКомплектацииНоменклатуры ПО ВариантыКомплектацииНоменклатурыТовары.Ссылка = ВариантыКомплектацииНоменклатуры.Ссылка ЛЕВОЕ СОЕДИНЕНИЕ Справочник.ВидыНоменклатуры КАК ВидыНоменклатуры ПО ВариантыКомплектацииНоменклатурыТовары.Номенклатура.ВидНоменклатуры = ВидыНоменклатуры.Ссылка ГДЕ ВариантыКомплектацииНоменклатуры.ВариантРасчетаЦеныНабора = ЗНАЧЕНИЕ(Перечисление.ВариантыРасчетаЦенНаборов.РассчитываетсяИзЦенКомплектующих) И (ВариантыКомплектацииНоменклатуры.Владелец, ВариантыКомплектацииНоменклатуры.Характеристика) В (ВЫБРАТЬ ВТ.Номенклатура КАК Номенклатура, ВТ.Характеристика КАК Характеристика ИЗ ВТ_Сопоставление КАК ВТ ГДЕ ВТ.ЭтоНабор) ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ ЦеныНоменклатуры.Номенклатура КАК Номенклатура, ЦеныНоменклатуры.Характеристика КАК Характеристика, ЕСТЬNULL(ЦеныНоменклатуры.Цена, 0) КАК Цена, ВЫБОР КОГДА ЦеныНоменклатуры.Упаковка.Числитель = 0 ТОГДА 1 ИНАЧЕ ЕСТЬNULL(ЦеныНоменклатуры.Упаковка.Числитель, 1) КОНЕЦ / ВЫБОР КОГДА ЦеныНоменклатуры.Упаковка.Знаменатель = 0 ТОГДА 1 ИНАЧЕ ЕСТЬNULL(ЦеныНоменклатуры.Упаковка.Знаменатель, 1) КОНЕЦ КАК КоэффициентУпаковкиЦена ПОМЕСТИТЬ ВТ_ЦеныТоваров ИЗ РегистрСведений.ЦеныНоменклатуры.СрезПоследних( , ВидЦены = &ВидЦены И (Номенклатура, Характеристика) В (ВЫБРАТЬ ВТ.Номенклатура КАК Номенклатура, ВТ.Характеристика КАК Характеристика ИЗ ВТ_Сопоставление КАК ВТ
ОБЪЕДИНИТЬ ВСЕ
ВЫБРАТЬ ВТ_СоставНаборов.НоменклатураНабора, ВТ_СоставНаборов.ХарактеристикаНабора ИЗ ВТ_СоставНаборов КАК ВТ_СоставНаборов)) КАК ЦеныНоменклатуры ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ ВТ_ЦеныТоваров.Номенклатура КАК Номенклатура, ВТ_ЦеныТоваров.Характеристика КАК Характеристика, СУММА(ВТ_ЦеныТоваров.Цена) КАК Цена, СУММА(ВТ_ЦеныТоваров.КоэффициентУпаковкиЦена) КАК КоэффициентУпаковкиЦена ПОМЕСТИТЬ ВТ_ЦеныТоваровОбъединениеЦен ИЗ ВТ_ЦеныТоваров КАК ВТ_ЦеныТоваров
СГРУППИРОВАТЬ ПО ВТ_ЦеныТоваров.Номенклатура, ВТ_ЦеныТоваров.Характеристика ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ ВТ_ЦеныТоваровОбъединениеЦен.Номенклатура КАК Номенклатура, ВТ_ЦеныТоваровОбъединениеЦен.Характеристика КАК Характеристика, ВТ_ЦеныТоваровОбъединениеЦен.Цена КАК Цена, ВЫБОР КОГДА ВТ_ЦеныТоваровОбъединениеЦен.КоэффициентУпаковкиЦена = 0 ТОГДА 1 ИНАЧЕ ВТ_ЦеныТоваровОбъединениеЦен.КоэффициентУпаковкиЦена КОНЕЦ КАК КоэффициентУпаковкиЦена ПОМЕСТИТЬ ВТ_ЦеныТоваровОбъединение ИЗ ВТ_ЦеныТоваровОбъединениеЦен КАК ВТ_ЦеныТоваровОбъединениеЦен ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ ВТ_СоставНаборов.РассчитываетсяИзЦенКомплектующих КАК РассчитываетсяИзЦенКомплектующих, ВТ_СоставНаборов.Номенклатура КАК Номенклатура, ВТ_СоставНаборов.Характеристика КАК Характеристика, ВТ_СоставНаборов.НоменклатураНабора КАК НоменклатураНабора, ВТ_СоставНаборов.ХарактеристикаНабора КАК ХарактеристикаНабора, СУММА(ВЫБОР КОГДА ЕСТЬNULL(ВТ_ЦеныТоваровОбъединение.Цена, 0) * ВТ_СоставНаборов.КоличествоНабора * ВТ_СоставНаборов.КоэффициентУпаковки / ЕСТЬNULL(ВТ_ЦеныТоваровОбъединение.КоэффициентУпаковкиЦена, 1) - 0.5 < 0 ТОГДА 0 ИНАЧЕ ВЫРАЗИТЬ(ЕСТЬNULL(ВТ_ЦеныТоваровОбъединение.Цена, 0) * ВТ_СоставНаборов.КоличествоНабора * ВТ_СоставНаборов.КоэффициентУпаковки / ЕСТЬNULL(ВТ_ЦеныТоваровОбъединение.КоэффициентУпаковкиЦена, 1) - 0.5 КАК ЧИСЛО(10, 0)) КОНЕЦ) КАК Цена ПОМЕСТИТЬ ВТ_ЦеныНаборовИтог ИЗ ВТ_СоставНаборов КАК ВТ_СоставНаборов ЛЕВОЕ СОЕДИНЕНИЕ ВТ_ЦеныТоваровОбъединение КАК ВТ_ЦеныТоваровОбъединение ПО ВТ_СоставНаборов.НоменклатураНабора = ВТ_ЦеныТоваровОбъединение.Номенклатура И ВТ_СоставНаборов.ХарактеристикаНабора = ВТ_ЦеныТоваровОбъединение.Характеристика
СГРУППИРОВАТЬ ПО ВТ_СоставНаборов.Номенклатура, ВТ_СоставНаборов.Характеристика, ВТ_СоставНаборов.РассчитываетсяИзЦенКомплектующих, ВТ_СоставНаборов.НоменклатураНабора, ВТ_СоставНаборов.ХарактеристикаНабора ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ ВТ_ЦеныНаборовИтог.РассчитываетсяИзЦенКомплектующих КАК РассчитываетсяИзЦенКомплектующих, ВТ_ЦеныНаборовИтог.Номенклатура КАК Номенклатура, ВТ_ЦеныНаборовИтог.Характеристика КАК Характеристика, СУММА(ЕСТЬNULL(ВТ_ЦеныНаборовИтог.Цена, 0)) КАК Цена ПОМЕСТИТЬ ВТ_ЦеныНаборов ИЗ ВТ_ЦеныНаборовИтог КАК ВТ_ЦеныНаборовИтог
СГРУППИРОВАТЬ ПО ВТ_ЦеныНаборовИтог.РассчитываетсяИзЦенКомплектующих, ВТ_ЦеныНаборовИтог.Номенклатура, ВТ_ЦеныНаборовИтог.Характеристика ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ ВТ_Сопоставление.НоменклатураOzon КАК НоменклатураOzon, ВТ_Сопоставление.Номенклатура КАК Номенклатура, ВТ_Сопоставление.Характеристика КАК Характеристика, ВЫБОР КОГДА ВТ_Сопоставление.ЭтоНабор И ВТ_ЦеныНаборов.РассчитываетсяИзЦенКомплектующих ТОГДА ВТ_ЦеныНаборов.Цена ИНАЧЕ ВЫБОР КОГДА ЕСТЬNULL(ВТ_ЦеныТоваровОбъединение.Цена, 0) * ВТ_Сопоставление.КоэффициентУпаковки / ЕСТЬNULL(ВТ_ЦеныТоваровОбъединение.КоэффициентУпаковкиЦена, 1) - 0.5 < 0 ТОГДА 0 ИНАЧЕ ВЫРАЗИТЬ(ЕСТЬNULL(ВТ_ЦеныТоваровОбъединение.Цена, 0) * ВТ_Сопоставление.КоэффициентУпаковки / ЕСТЬNULL(ВТ_ЦеныТоваровОбъединение.КоэффициентУпаковкиЦена, 1) - 0.5 КАК ЧИСЛО(10, 0)) КОНЕЦ КОНЕЦ КАК Цена ПОМЕСТИТЬ ВТ_ЦеныОбъединение ИЗ ВТ_Сопоставление КАК ВТ_Сопоставление ЛЕВОЕ СОЕДИНЕНИЕ ВТ_ЦеныТоваровОбъединение КАК ВТ_ЦеныТоваровОбъединение ПО ВТ_Сопоставление.Номенклатура = ВТ_ЦеныТоваровОбъединение.Номенклатура И ВТ_Сопоставление.Характеристика = ВТ_ЦеныТоваровОбъединение.Характеристика ЛЕВОЕ СОЕДИНЕНИЕ ВТ_ЦеныНаборов КАК ВТ_ЦеныНаборов ПО ВТ_Сопоставление.Номенклатура = ВТ_ЦеныНаборов.Номенклатура И ВТ_Сопоставление.Характеристика = ВТ_ЦеныНаборов.Характеристика ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ ВТ_Сопоставление.НоменклатураOzon КАК НоменклатураOzon, ВТ_Сопоставление.Номенклатура КАК Номенклатура, ВТ_Сопоставление.Характеристика КАК Характеристика, ВЫРАЗИТЬ(ВТ_ЦеныОбъединение.Цена КАК ЧИСЛО(10, 0)) КАК Цена ИЗ ВТ_Сопоставление КАК ВТ_Сопоставление ЛЕВОЕ СОЕДИНЕНИЕ ВТ_ЦеныОбъединение КАК ВТ_ЦеныОбъединение ПО ВТ_Сопоставление.НоменклатураOzon = ВТ_ЦеныОбъединение.НоменклатураOzon
